changeSet.sql:
DO $$
DECLARE
  v_has_audit_trigger boolean := EXISTS (
    SELECT 1
    FROM pg_trigger
    WHERE tgname = 'trg_amendment_audit_glasgow_coma_scale_assessment'
      AND tgrelid = 'public.glasgow_coma_scale_assessment'::regclass
  );
BEGIN
  IF v_has_audit_trigger THEN
    ALTER TABLE public.glasgow_coma_scale_assessment
      DISABLE TRIGGER trg_amendment_audit_glasgow_coma_scale_assessment;
  END IF;

  UPDATE public.glasgow_coma_scale_assessment
  SET score_interpretation = CASE
                               WHEN score_interpretation ~ '^[0-9]+$' THEN '3'
                               ELSE 'NORMAL'
                             END
  WHERE total_score = 15
    AND score_interpretation IN ('0', 'MILD_TRAUMATIC_BRAIN_INJURY');

  IF v_has_audit_trigger THEN
    ALTER TABLE public.glasgow_coma_scale_assessment
      ENABLE TRIGGER trg_amendment_audit_glasgow_coma_scale_assessment;
  END IF;
END
$$;

rollback.sql:
DO $$
DECLARE
  v_has_audit_trigger boolean := EXISTS (
    SELECT 1
    FROM pg_trigger
    WHERE tgname = 'trg_amendment_audit_glasgow_coma_scale_assessment'
      AND tgrelid = 'public.glasgow_coma_scale_assessment'::regclass
  );
BEGIN
  IF v_has_audit_trigger THEN
    ALTER TABLE public.glasgow_coma_scale_assessment
      DISABLE TRIGGER trg_amendment_audit_glasgow_coma_scale_assessment;
  END IF;

  UPDATE public.glasgow_coma_scale_assessment
  SET score_interpretation = CASE
                               WHEN score_interpretation ~ '^[0-9]+$' THEN '0'
                               ELSE 'MILD_TRAUMATIC_BRAIN_INJURY'
                             END
  WHERE total_score = 15
    AND score_interpretation IN ('3', 'NORMAL');

  IF v_has_audit_trigger THEN
    ALTER TABLE public.glasgow_coma_scale_assessment
      ENABLE TRIGGER trg_amendment_audit_glasgow_coma_scale_assessment;
  END IF;
END
$$;
